pous.declaration:
FUNCTION_BLOCK MotorCtrl
VAR_INPUT
    StartBtn : BOOL;
    StopBtn : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Motor : BOOL;
END_VAR

pous.implementation:
(* stop and e-stop have priority over start *)
IF StopBtn OR EStop THEN
    Motor := FALSE;
ELSIF StartBtn THEN
    Motor := TRUE;
END_IF

counter := counter + 1;
IF counter > 100 THEN
    counter := 0;
END_IF

pous.declaration:
FUNCTION SwapInOut : BOOL
VAR_IN_OUT
    a : INT;
    b : INT;
END_VAR
VAR
    t : INT;
END_VAR

pous.implementation:
t := a;
a := b;
b := t;
SwapInOut := TRUE;
bad_inout_var := 1;

pous.declaration:
FUNCTION Helper : INT
VAR_INPUT
    x : INT;
    y : INT;
END_VAR

pous.implementation:
IF run THEN
    out := Helper(1, 2);
ELSE
    out := 0;
END_IF

